class ContinuousBatchScheduler:
    def __init__(self, max_batch_size: int, max_tokens: int):
        self.max_batch_size = max_batch_size
        self.max_tokens = max_tokens
        self.running_batch = []
        self.waiting_queue = []

    # Iteration-level scheduling: inject new prompts into the batch at every token generation step
    def step(self):
        # BUG: Static batching blocks until all sequences complete
        if any(not req.is_finished() for req in self.running_batch):
            return self.forward_decode()
        self.running_batch = self.waiting_queue[:self.max_batch_size]
        return self.forward_prefill()
